{"content": "from functools import lru_cache
import sys

sys.setrecursionlimit(2000)

@lru_cache(maxsize=None)
def fib_cached(n: int) -> int:
    """Computes the n-th Fibonacci number using memoized recursion."""
    if n < 0:
        raise ValueError("Fibonacci is not defined for negative numbers.")
    if n < 2:
        return n
    return fib_cached(n - 1) + fib_cached(n - 2)

def fib_iterative(n: int) -> int:
    """Computes the n-th Fibonacci number iteratively in O(n) time and O(1) space."""
    if n < 0:
        raise ValueError("Fibonacci is not defined for negative numbers.")
    if n < 2:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def fib_matrix(n: int) -> int:
    """Computes the n-th Fibonacci number using matrix exponentiation in O(log n) time."""
    if n < 0:
        raise ValueError("Fibonacci is not defined for negative numbers.")
    if n == 0:
        return 0

    def matrix_mult(A, B):
        return [
            [A[0][0]*B[0][0] + A[0][1]*B[1][0], A[0][0]*B[0][1] + A[0][1]*B[1][1]],
            [A[1][0]*B[0][0] + A[1][1]*B[1][0], A[1][0]*B[0][1] + A[1][1]*B[1][1]]
        ]

    def matrix_pow(F, p):
        res = [[1, 0], [0, 1]]
        base = F
        while p > 0:
            if p & 1:
                res = matrix_mult(res, base)
            base = matrix_mult(base, base)
            p >>= 1
        return res

    F = [[1, 1], [1, 0]]
    res = matrix_pow(F, n - 1)
    return res[0][0]
